	'messages:apihelp-compare-param-fromcontentmodel' => 'zh-hant:指定 <kbd>fromslots=main</kbd> 並改使用 <var>fromcontentmodel-main</var>。',
	'messages:apihelp-compare-param-fromcontentformat' => 'zh-hant:指定 <kbd>fromslots=main</kbd> 並改使用 <var>fromcontentformat-main</var>。',
	'messages:apihelp-compare-param-fromsection' => 'zh-hant:僅使用 \'from\' 內容的指定段落。',
	'messages:apihelp-compare-param-totitle' => 'zh-hant:要比對的第二個標題。',
